test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('prices that are off by float error keep their exact cents', () => {
  assert.deepStrictEqual(invoice([{ name: 'A', price: '19.99', qty: 1 }, { name: 'B', price: '0.29', qty: 1 }]),
    ['A: 19.99', 'B: 0.29', 'Total: 20.28']);
});

test('refund lines print as a single negative amount', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-19.99', qty: 1 }]), ['Refund: -19.99', 'Total: -19.99']);
});

test('percent discount rounds to the nearest cent', () => {
  // subtotal 1999 cents * 10% = 199.9 -> 200 cents
  assert.deepStrictEqual(invoice([{ name: 'A', price: '19.99', qty: 1 }], 10),
    ['A: 19.99', 'Discount: -2.00', 'Total: 17.99']);
});

